-- Conferência: a coluna "registros" deve ser igual à coluna "esperado".
select 'Usuários de teste' as tabela, count(*) as registros, 13 as esperado from public.usuarios where codigo_legado >= 9000
union all select 'Clientes fictícios', count(*), 300 from public.clientes where codigo_legado >= 90000
union all select 'Propostas fictícias', count(*), 200 from public.propostas where codigo like '9%'
union all select 'Produtos', count(*), 439 from public.produtos;
